require_once __DIR__.'/auth.php';require_member_login();$mid=(int)member_user()['member_id'];$bid=(int)member_user()['branch_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='book_class'){$cid=(int)$_POST['class_id'];$valid=query_value("SELECT COUNT(*) FROM classes WHERE id=? AND branch_id=? AND status='active'",[$cid,$bid]);$m=query_one("SELECT status,membership_end FROM members WHERE id=?",[$mid]);if($valid&&$m&&$m['status']==='active'&&strtotime($m['membership_end'])>=strtotime(date('Y-m-d'))){$cap=(int)query_value("SELECT capacity FROM classes WHERE id=?",[$cid]);$booked=(int)query_value("SELECT COUNT(*) FROM class_bookings WHERE class_id=? AND status IN('booked','attended')",[$cid]);$status=$booked<$cap?'booked':'waitlist';db()->prepare("INSERT INTO class_bookings(class_id,member_id,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)")->execute([$cid,$mid,$status]);flash('success',$status==='booked'?'Class booked.':'Class is full; you were added to the waitlist.');}redirect('member/dashboard.php');}}
$m=query_one("SELECT m.*,p.name plan_name,p.price,t.name trainer_name,b.name branch_name FROM members m LEFT JOIN membership_plans p ON p.id=m.membership_plan_id LEFT JOIN trainers t ON t.id=m.trainer_id JOIN branches b ON b.id=m.branch_id WHERE m.id=?",[$mid]);
$att=query_all("SELECT * FROM attendance WHERE member_id=? ORDER BY check_in DESC LIMIT 8",[$mid]);
$pay=query_all("SELECT * FROM payments WHERE member_id=? ORDER BY payment_date DESC,id DESC LIMIT 8",[$mid]);
$workouts=query_all("SELECT w.*,t.name trainer_name FROM workout_plans w LEFT JOIN trainers t ON t.id=w.trainer_id WHERE w.member_id=? ORDER BY w.created_at DESC LIMIT 4",[$mid]);
$diets=query_all("SELECT d.*,t.name trainer_name FROM diet_plans d LEFT JOIN trainers t ON t.id=d.trainer_id WHERE d.member_id=? ORDER BY d.created_at DESC LIMIT 3",[$mid]);
$dietItems=[];if($diets){$dietItems=query_all("SELECT * FROM diet_items WHERE diet_plan_id=? ORDER BY id",[$diets[0]['id']]);}
$metrics=query_all("SELECT * FROM body_metrics WHERE member_id=? ORDER BY recorded_on ASC",[$mid]);
$classes=query_all("SELECT c.*,t.name trainer_name,(SELECT status FROM class_bookings b WHERE b.class_id=c.id AND b.member_id=? LIMIT 1) my_status,(SELECT COUNT(*) FROM class_bookings x WHERE x.class_id=c.id AND x.status IN('booked','attended')) booked FROM classes c LEFT JOIN trainers t ON t.id=c.trainer_id WHERE c.branch_id=? AND c.status='active' ORDER BY FIELD(c.recurring_day,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'),c.start_time",[$mid,$bid]);
$visits=(int)query_value("SELECT COUNT(*) FROM attendance WHERE member_id=? AND check_in>=DATE_SUB(NOW(),INTERVAL 30 DAY)",[$mid]);$effective=strtotime($m['membership_end'])<strtotime(date('Y-m-d'))?'expired':$m['status'];$flashes=get_flashes();
?>
